// Portable display index — record JAH-GPCS-PORTABLEMONITOR-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"refresh_hz": 60, "res_mp": 2.1, "price_usd": 150};
var value = (m.refresh_hz*m.res_mp/m.price_usd*100);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-PORTABLEMONITOR-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-PORTABLEMONITOR-000001|' + value.toFixed(2) + ' display index');

